arguments.command:
cat > /tmp/gh-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) printf '%s\n' 'x-access-token' ;;
  *[Pp]assword*) printf '%s\n' "$GITHUB_TOKEN" ;;
  *) printf '%s\n' '' ;;
esac
EOF
chmod 700 /tmp/gh-askpass.sh && cd /home/runner/work/beetle-in-the-anthill/monica-conv && GIT_ASKPASS=/tmp/gh-askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/monica 2>&1 | tail -5
